Q: Removing overlapping faces in 3dsmax A: <p>here is an improved version based  on the original script:</p>
<pre><code>-- Written By Colin Senner (v1.04 - Overlapping Face Detection, robust normals)
-- www.colinsenner.com
--
-- CHANGELOG v1.04:
--   - Fixed normal comparison: now uses dot product with tolerance instead of exact equality
--   - Fixed Editable_Mesh: uses meshOp.getFaceNormal (single face normal) instead of
--     getFaceRNormals (per-vertex normals array) for reliable comparison
--   - Increased default tolerance and made both center + normal tolerances tunable
--   - Should now correctly detect all overlapping faces that XView reports

-- Functions
global trim_dupsArray
global findOverlappingPolyFaces
global findOverlappingMeshFaces
global findCoinstancedObjects
global compareOverlapPoly
global compareOverlapMesh
global deleteOverlappingPolyFaces
global deleteOverlappingMeshFaces

-- Rollouts
global rlt_findOverlap

-- Tolerances (tweak these if your scene uses a different unit scale)
global overlapCenterTolerance   -- max distance between face centers to be considered overlapping
global overlapNormalTolerance   -- how close dot product must be to 1.0 (or -1.0) for normals to match
overlapCenterTolerance = 0.01
overlapNormalTolerance = 0.9999  -- dot product threshold (1.0 = identical, lower = more lenient)

if rlt_findOverlap != undefined then destroyDialog rlt_findOverlap


rollout rlt_findOverlap &quot;Find Overlapping Faces 1.04&quot; (

    dropDownList lst_todo items:#(&quot;Select Only Duplicates&quot;,&quot;Select All&quot;,&quot;Find &amp; Delete Duplicates&quot;) selection:1 width:150
    button btn_Find &quot;Find&quot; width:75
    button btn_Help &quot;?&quot; offset:[65,-24] height:16 width:20

    on lst_todo selected sel do ( todo = sel )

    on btn_Help pressed do (
        local txt = &quot;&quot;
        txt += &quot;Help Dialog v1.04 - Find Overlapping Faces, by Colin Senner\n\n&quot;
        txt += &quot;What are Overlapping Faces?\n&quot;
        txt += &quot;   Faces that share the same position and orientation in 3D space,\n&quot;
        txt += &quot;   stacked directly on top of each other. This causes render flickering\n&quot;
        txt += &quot;   and shading artifacts (Z-fighting).\n\n&quot;
        txt += &quot;This tool works in two modes:\n\n&quot;
        txt += &quot;   1. SINGLE OBJECT selected:\n&quot;
        txt += &quot;      Finds faces within that object that overlap each other.\n&quot;
        txt += &quot;      'Select Only Duplicates' - selects just the redundant copies\n&quot;
        txt += &quot;      'Select All'             - selects all faces involved in overlaps\n&quot;
        txt += &quot;      'Find &amp; Delete Duplicates' - deletes the redundant faces and\n&quot;
        txt += &quot;                                   reports how many were removed\n\n&quot;
        txt += &quot;   2. MULTIPLE OBJECTS selected:\n&quot;
        txt += &quot;      Finds and selects objects that are cloned on top of each other.\n\n&quot;
        txt += &quot;NOTE: Delete operation supports Undo (Ctrl+Z)\n&quot;
        messagebox txt title:&quot;Help&quot; beep:false
    )

    on btn_Find pressed do (
        local objs = getCurrentSelection()

        if objs.count == 1 then (
            if classof objs[1] == Editable_Poly then (
                if lst_todo.selection == 1 then (
                    local dupFaces = (findOverlappingPolyFaces objs[1] returnOnlyDupes:true)
                    objs[1].selectedFaces = dupFaces
                    subObjectLevel = 4
                ) else if lst_todo.selection == 2 then (
                    local dupFaces = (findOverlappingPolyFaces objs[1] returnOnlyDupes:false)
                    objs[1].selectedFaces = dupFaces
                    subObjectLevel = 4
                ) else if lst_todo.selection == 3 then (
                    local deletedCount = (deleteOverlappingPolyFaces objs[1])
                    if deletedCount == 0 then
                        messageBox &quot;No overlapping faces found.&quot; title:&quot;Done&quot; beep:false
                    else
                        messageBox (&quot;Job complete!\n&quot; + deletedCount as string + &quot; overlapping face(s) were deleted.&quot;) title:&quot;Done&quot; beep:false
                )

            ) else if classof objs[1] == Editable_Mesh then (
                if lst_todo.selection == 1 then (
                    local dupFaces = (findOverlappingMeshFaces objs[1] returnOnlyDupes:true)
                    objs[1].selectedFaces = dupFaces
                    subObjectLevel = 4
                ) else if lst_todo.selection == 2 then (
                    local dupFaces = (findOverlappingMeshFaces objs[1] returnOnlyDupes:false)
                    objs[1].selectedFaces = dupFaces
                    subObjectLevel = 4
                ) else if lst_todo.selection == 3 then (
                    local deletedCount = (deleteOverlappingMeshFaces objs[1])
                    if deletedCount == 0 then
                        messageBox &quot;No overlapping faces found.&quot; title:&quot;Done&quot; beep:false
                    else
                        messageBox (&quot;Job complete!\n&quot; + deletedCount as string + &quot; overlapping face(s) were deleted.&quot;) title:&quot;Done&quot; beep:false
                )

            ) else (
                messageBox &quot;Please select an Editable Poly or Editable Mesh object.&quot; title:&quot;Error&quot; beep:false
                return false
            )

        ) else if objs.count &gt; 1 then (
            clearSelection()
            local dupObjs = (findCoinstancedObjects objs)
            if dupObjs.count == 0 then
                messageBox &quot;No overlapping objects found.&quot; title:&quot;Done&quot; beep:false
            else
                select dupObjs
        ) else (
            messageBox &quot;Please select at least one object.&quot; title:&quot;Error&quot; beep:false
        )
    )
)
createDialog rlt_findOverlap 180 65


-- ============================================================
-- HELPER: Dot-product based normal comparison
-- Returns true if two normals are parallel (same or opposite direction)
-- ============================================================
fn normalsAreParallel nrmA nrmB = (
    local a = normalize nrmA
    local b = normalize nrmB
    local d = dot a b
    -- d close to  1.0 =&gt; same direction
    -- d close to -1.0 =&gt; opposite direction (front/back of same face)
    (d &gt;= overlapNormalTolerance) or (d &lt;= -overlapNormalTolerance)
)


-- ============================================================
-- POLY FUNCTIONS
-- ============================================================

fn findOverlappingPolyFaces obj returnOnlyDupes:false = (
    local objArrSFC = #()
    local objArrNrm = #()
    local dupFaces = #{}

    if classof obj != Editable_Poly then return undefined

    for i = 1 to obj.faces.count do (
        objArrSFC[i] = (polyOp.getSafeFaceCenter obj i)
        objArrNrm[i] = (polyOp.getFaceNormal obj i)
    )

    dupFaces = (compareOverlapPoly objArrSFC objArrNrm returnOnlyDupes:returnOnlyDupes)
    dupFaces
)


fn compareOverlapPoly arrSFC arrNrm returnOnlyDupes:false = (
    local dupBitArr = #{}

    for i = 1 to arrSFC.count do (
        for j = (i + 1) to arrSFC.count do (
            if (distance arrSFC[i] arrSFC[j]) &lt;= overlapCenterTolerance then (
                if (normalsAreParallel arrNrm[i] arrNrm[j]) then (
                    dupBitArr[j] = true
                    if not(returnOnlyDupes) then
                        dupBitArr[i] = true
                )
            )
        )
    )
    dupBitArr
)


fn deleteOverlappingPolyFaces obj = (
    if classof obj != Editable_Poly then return 0

    local dupFaces = (findOverlappingPolyFaces obj returnOnlyDupes:true)
    local deletedCount = 0

    if dupFaces.numberSet &gt; 0 then (
        deletedCount = dupFaces.numberSet
        undo &quot;Delete Overlapping Poly Faces&quot; on (
            polyOp.deleteFaces obj dupFaces delIsoVerts:false
        )
    )
    deletedCount
)


-- ============================================================
-- MESH FUNCTIONS
-- ============================================================

fn findOverlappingMeshFaces obj returnOnlyDupes:false = (
    local objArrSFC = #()
    local objArrNrm = #()
    local dupFaces = #{}

    if classof obj != Editable_Mesh then return undefined

    for i = 1 to obj.faces.count do (
        objArrSFC[i] = (meshOp.getFaceCenter obj i)
        -- getFaceNormal returns a single Point3 face normal (reliable, NOT per-vertex array)
        objArrNrm[i] = (meshOp.getFaceNormal obj i)
    )

    dupFaces = (compareOverlapMesh objArrSFC objArrNrm returnOnlyDupes:returnOnlyDupes)
    dupFaces
)


fn compareOverlapMesh arrSFC arrNrm returnOnlyDupes:false = (
    local dupBitArr = #{}

    for i = 1 to arrSFC.count do (
        for j = (i + 1) to arrSFC.count do (
            if (distance arrSFC[i] arrSFC[j]) &lt;= overlapCenterTolerance then (
                if (normalsAreParallel arrNrm[i] arrNrm[j]) then (
                    dupBitArr[j] = true
                    if not(returnOnlyDupes) then
                        dupBitArr[i] = true
                )
            )
        )
    )
    dupBitArr
)


fn deleteOverlappingMeshFaces obj = (
    if classof obj != Editable_Mesh then return 0

    local dupFaces = (findOverlappingMeshFaces obj returnOnlyDupes:true)
    local deletedCount = 0

    if dupFaces.numberSet &gt; 0 then (
        deletedCount = dupFaces.numberSet
        undo &quot;Delete Overlapping Mesh Faces&quot; on (
            meshOp.deleteFaces obj dupFaces
            update obj
        )
    )
    deletedCount
)


-- ============================================================
-- OBJECT-LEVEL FUNCTIONS
-- ============================================================

fn findCoinstancedObjects arr = (
    local dupObjs = #()

    for o in arr do (
        for j in arr where o != j do (
            if ((o.transform as string) == (j.transform as string)) and \
               (o.min == j.min) and (o.max == j.max) and (o.wirecolor == j.wirecolor) then (
                append dupObjs j
                j.wirecolor = color 250 243 210
            )
        )
    )
    trim_dupsArray dupObjs
)


fn trim_dupsArray a = (
    for i = a.count to 1 by -1 do (
        local idx = findItem a a[i]
        if (idx != 0) and (idx != i) do (
            deleteItem a i
        )
    )
    a
)
</code></pre>

Q: Can R&#39;s htmltools::includeHTML not handle leaflet maps? A: <p>Use <code>htmltools::tags$iframe</code> instead! To make your MRE work, you simply need a <code>print()</code> inside <code>for</code>. But I would recommend to just build the maps and tables in one go using <a href="https://stackoverflow.com/a/79903155/28479453">this approach</a>. <a href="https://stackoverflow.com/a/79625093/28479453">Here</a> is how to build nested tabsets.</p>
<p><strong>report_include_html.Rmd</strong></p>
<pre><code>---
title: &quot;Test&quot;
author: &quot;SQC&quot;
date: &quot;11 Juli 2019&quot;
output: html_document
---

```{r setup, include=FALSE}
knitr::opts_chunk$set(echo = FALSE)
library(leaflet)
```

# Title level 1

This is an R Markdown document. 

## Title level 2 (tab) {.tabset}

### Title level 3 (tab) {.tabset}

```{r, echo = FALSE, results='asis'}

show_iframe &lt;- \(src){
  print(
    htmltools::tags$iframe(
      src = src,
      width = &quot;100%&quot;,
      style = &quot;height: 100vh&quot;,
      frameBorder = &quot;0&quot;
    )
  )
}

for (i in 2:length(ranges)) {
  cat(paste0(&quot;#### Title level 4 `r &quot;, 
             ranges[i], &quot;` vs. `r &quot;, ranges[i - 1], &quot;` {.tabset}\n&quot;))

  cat(&quot;##### Map\n&quot;)
  show_iframe(paste0(save_path, &quot;helper_map_&quot;, i, &quot;.html&quot;))


  cat(&quot;##### Tabelle\n&quot;)
  show_iframe(paste0(save_path, &quot;helper_table_&quot;, i, &quot;.html&quot;))
}
```

### Title level 3 (tab) {.tabset}

```{r, echo = FALSE, results='asis'}
