  cat(paste0(&quot;#### `r &quot;, ranges[i], &quot;` vs. `r &quot;, ranges[i - 1], &quot;` {.tabset}\n&quot;))

  cat(&quot;##### Map\n&quot;)
  show_iframe(paste0(save_path, &quot;helper_map_&quot;, i, &quot;.html&quot;))

  cat(&quot;##### Tabelle\n&quot;)
